        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        SftRun(emon.Testport.TextBlob("PAID 2026-03-14"), et, @out, 2, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 1, "year first, one separator: a date nothing disputes");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 3), 5, "it starts after PAID");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 4), 10, "and is ten characters");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 5), 2026, "the year");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 6), 3, "the month");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 7), 14, "the day");
        SftRun(emon.Testport.TextBlob("Date: 2026/4/2."), et, @out, 2, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 6), 4, "a slash and one-digit parts");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 7), 2, "the day, 2");
        SftRun(emon.Testport.TextBlob("14.03.2026"), et, @out, 1, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 1, "a day over 12 first: the day, then the month");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 6), 3, "month 3");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 7), 14, "day 14");
        SftRun(emon.Testport.TextBlob("03/14/2026"), et, @out, 1, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 6), 3, "a second number over 12 is the day, whatever the order");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 7), 14, "so the first is the month");
        SftRun(emon.Testport.TextBlob("03/04/2026"), et, @out, 1, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 2, "both numbers at most 12 and with no hint: the text as it stands");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 4), 10, "its ten characters");
        SftRun(emon.Testport.TextBlob("03/04/2026"), et, @out, 1, 2);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 1, "month first by the hint");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 6), 3, "month 3");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 7), 4, "day 4");
        SftRun(emon.Testport.TextBlob("03/04/2026"), et, @out, 1, 1);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 6), 4, "day first by the hint: month 4");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 7), 3, "day 3");
        SftRun(emon.Testport.TextBlob("05/05/2026"), et, @out, 1, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 1, "the same number twice is the same either way");
        SftRun(emon.Testport.TextBlob("SEALED 12.5.24"), et, @out, 1, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 2, "a two-digit year is a date's shape only: as it stands");
        SftRun(emon.Testport.TextBlob("NO DIGITS HERE"), et, @out, 1, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 0, "a text with no digits has no date");
        SftRun(emon.Testport.TextBlob("REG 20261 AND 99"), et, @out, 1, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 0, "numbers that are no date shape are none");
        SftRun(emon.Testport.TextBlob("2026-13-40"), et, @out, 1, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 0, "a month of 13 is no date");
