    [Xunit.Fact]
    public static void TestTheLocaleHintOrdersANumericDate() {
        emon.Port.Cells loc = emon.Port.NewCells();
        SftPut(emon.Testport.TextBlob("en-US"), loc);
        emon.Testport.AssertEq(Sealfield.SfOrder(loc), 2, "US: month first");
        SftPut(emon.Testport.TextBlob("en_US"), loc);
        emon.Testport.AssertEq(Sealfield.SfOrder(loc), 2, "with an underscore too");
        SftPut(emon.Testport.TextBlob("de-DE"), loc);
        emon.Testport.AssertEq(Sealfield.SfOrder(loc), 1, "Germany: day first");
        SftPut(emon.Testport.TextBlob("ja"), loc);
        emon.Testport.AssertEq(Sealfield.SfOrder(loc), 1, "a language alone: day first");
        SftPut(emon.Testport.TextBlob(""), loc);
        emon.Testport.AssertEq(Sealfield.SfOrder(loc), 0, "no hint: none");
        emon.Testport.AssertThat(Sealfield.SfPrep(loc, 0) >= 0, "the answer's scratch is made");
        emon.Testport.AssertEq(emon.Port.CellsLen(loc), 32, "of 32 cells");
        Sealfield.SfPrep(loc, 20);
        emon.Testport.AssertEq(emon.Port.CellsLen(loc), 52, "and from another cell, after it");
    }
